import math

def _isnum(x):
    return isinstance(x, float) and math.isfinite(x)

def precondition(*args):
    try:
        return len(args) == 1 and isinstance(args[0], list) and len(args[0]) >= 2 and all(_isnum(x) for x in args[0])
    except Exception:
        return False

