def prop_no_closer_pair(candidate, numbers):
    a, b = candidate(copy.deepcopy(numbers))
    d = b - a
    for i in range(len(numbers)):
        for j in range(i + 1, len(numbers)):
            assert abs(numbers[i] - numbers[j]) >= d

import copy
def prop_adding_element_gap_not_larger(candidate, numbers):
    if len(numbers) >= 3:
        a, b = candidate(copy.deepcopy(numbers[:-1]))
        c, d = candidate(copy.deepcopy(numbers))
        assert d - c <= b - a

